mapper.select:
-- 核心：先在3857生成准确米级缓冲区，再转回4326，最后转为WKT
SELECT ST_AsText(
               -- 步骤2：在3857坐标系下生成圆形缓冲区
               ST_Buffer(
                   -- 步骤1：将圆心WKT（4326）转换为3857坐标系
                   ST_Transform(
                       ST_GeomFromText(#{bo.centerWkt}, 4326),
                       3857
                   ),
                   #{bo.radius} -- 半径（单位：米）
               )
       )  AS circle_wkt_3857;

-- 核心：先在3857生成准确米级缓冲区，再转回4326，最后转为WKT
SELECT ST_AsText(
           -- 步骤3：将3857缓冲区转回4326坐标系（经纬度）
           ST_Transform(
               -- 步骤2：在3857坐标系下生成圆形缓冲区
               ST_Buffer(
                   -- 步骤1：将圆心WKT（4326）转换为3857坐标系
                   ST_Transform(
                       ST_GeomFromText(#{bo.centerWkt}, 4326),
                       3857
                   ),
                   #{bo.radius} -- 半径（单位：米）
               ),
               4326 -- 目标坐标系：4326（经纬度）
           )
       ) AS circle_wkt_4326;
